<script setup>
import {ref,onMounted,computed} from 'vue'
import {api,session} from '../api'
import Icon from '../components/Icon.vue'
import GradeTable from '../components/GradeTable.vue'
import PerformanceChart from '../components/PerformanceChart.vue'
const data=ref(null),error=ref(''),month=ref('2026-10'),busy=ref(false)
const date=new Intl.DateTimeFormat('es-SV',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'America/El_Salvador'}).format(new Date())
const cards=computed(()=>[{label:'Estudiantes registrados',value:data.value?.stats?.students??0,icon:'Users',color:'blue',note:'Comunidad estudiantil'},{label:session.user?.role==='admin'?'Docentes activos':'Grupos asignados',value:session.user?.role==='admin'?data.value?.stats?.teachers??0:data.value?.stats?.groups??0,icon:'UserRound',color:'purple',note:session.user?.role==='admin'?'Equipo académico':'En tu espacio académico'},{label:'Grupos académicos',value:data.value?.stats?.groups??0,icon:'Layers',color:'orange',note:'Asignaturas organizadas'},{label:'Promedio general',value:(data.value?.stats?.average??0).toFixed(2),icon:'ChartNoAxesCombined',color:'green',note:'Escala de 0.00 a 10.00'}])
async function load(){busy.value=true;error.value='';try{data.value=await api('/dashboard?month='+month.value)}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-heading summary-heading"><div><div class="eyebrow">TU ESPACIO ACADÉMICO</div><h1>Resumen general<span class="heading-dot">.</span></h1><p>Bienvenido, {{session.user?.name?.split(' ')[0]}}. Así va nuestra comunidad académica.</p></div><div class="summary-actions"><span class="summary-date">{{date}}</span><v-btn to="/notas" color="secondary">{{session.user?.role==='student'?'Mis notas':'Gestionar notas'}}</v-btn></div></div>
<v-alert v-if="error" type="error" variant="tonal" class="mb-5">{{error}} <button @click="load">Reintentar</button></v-alert><v-progress-linear v-if="busy" indeterminate color="primary" class="mb-4"/>

<section v-if="session.user?.role!=='student'" class="stat-grid summary-stats"><article v-for="card in cards" :key="card.label" class="stat-card"><div class="stat-top"><span>{{card.label}}</span><span class="stat-icon" :class="card.color"><Icon :name="card.icon" :size="21"/></span></div><strong class="stat-value">{{card.value}}</strong></article></section>
<section class="dashboard-middle" :class="{'student-dashboard':session.user?.role==='student'}"><article class="panel recent-panel"><div class="panel-heading"><div><h2>Notas recientes</h2><p>Últimas evaluaciones registradas en el período.</p></div><router-link to="/notas" class="text-link">Ver todas <Icon name="ArrowUpRight" :size="16"/></router-link></div><GradeTable :rows="data?.recent||[]"/><div class="panel-bottom-note"><Icon name="RefreshCw" :size="13"/> Información actualizada al consultar el panel.</div></article><article v-if="session.user?.role!=='student'" class="panel performance-panel"><div class="panel-heading"><div><h2>Rendimiento académico</h2><p>Promedio por estudiante</p></div></div><div class="month-filter"><Icon name="CalendarDays" :size="15"/><input aria-label="Mes del rendimiento" type="month" v-model="month" @change="load"/></div><PerformanceChart :passed="data?.stats?.passed||0" :failed="data?.stats?.failed||0"/><div class="chart-footnote">Nota mínima de aprobación: <strong>6.00</strong></div></article></section>
<section class="dashboard-bottom" :class="{'student-dashboard':session.user?.role==='student'}"><article class="panel groups-panel"><div class="panel-heading"><div><h2>Grupos académicos</h2><p>Asignaturas del ciclo.</p></div><router-link to="/grupos" class="text-link">Ver grupos <Icon name="ArrowUpRight" :size="16"/></router-link></div><div class="group-card-grid"><router-link v-for="(g,i) in data?.groups||[]" :key="g.id" :to="'/notas?group='+g.id" class="mini-group"><span class="group-icon" :class="'group-color-'+i"><Icon name="BookOpen" :size="20"/></span><span class="mini-group-code">{{g.code}} <Icon name="ArrowUpRight" :size="15"/></span><h3>{{g.subject}}</h3><p>{{g.teacher?.name}}</p><div><span><Icon name="Users" :size="14"/> {{g.students_count}} estudiantes</span><small>{{g.cycle}}</small></div></router-link><div v-if="data&&!data.groups.length" class="empty-state">Todavía no hay grupos asignados.</div></div></article><article v-if="session.user?.role!=='student'" class="report-callout"><span class="report-callout-icon"><Icon name="FileText" :size="25"/></span><h2>Informes</h2><p>Genera cuadros de notas y consulta el progreso de tus estudiantes.</p><router-link to="/informes">Explorar informes <Icon name="ArrowRight" :size="17"/></router-link></article></section>
</template>
